2231	  /**
2232	   * POST /api/plugins/:pluginId/webhooks/:endpointKey
2233	   *
2234	   * Receive an inbound webhook delivery for a plugin.
2235	   *
2236	   * This route is called by external systems (e.g. GitHub, Linear, Stripe) to
2237	   * deliver webhook payloads to a plugin. The host validates that:
2238	   * 1. The plugin exists and is in 'ready' state
2239	   * 2. The plugin declares the `webhooks.receive` capability
2240	   * 3. The `endpointKey` matches a declared webhook in the manifest
2241	   *
2242	   * The delivery is recorded in the `plugin_webhook_deliveries` table and
2243	   * dispatched to the worker via the `handleWebhook` RPC method.
2244	   *
2245	   * **Note:** This route does NOT require board authentication — webhook
2246	   * endpoints must be publicly accessible for external callers. Signature
2247	   * verification is the plugin's responsibility.
2248	   *
2249	   * Response: `{ deliveryId: string, status: string }`
2250	   * Errors:
2251	   * - 404 if plugin not found or endpointKey not declared
2252	   * - 400 if plugin is not in ready state or lacks webhooks.receive capability
2253	   * - 502 if the worker is unavailable or the RPC call fails
2254	   */
2255	  router.post("/plugins/:pluginId/webhooks/:endpointKey", async (req, res) => {
2256	    if (!webhookDeps) {
2257	      res.status(501).json({ error: "Webhook ingestion is not enabled" });
2258	      return;
2259	    }
2260	
2261	    const { pluginId, endpointKey } = req.params;
2262	
2263	    // Step 1: Resolve the plugin
2264	    const plugin = await resolvePlugin(registry, pluginId);
2265	    if (!plugin) {
2266	      res.status(404).json({ error: "Plugin not found" });
2267	      return;
2268	    }
2269	
2270	    // Step 2: Validate the plugin is in 'ready' state
2271	    if (plugin.status !== "ready") {
2272	      res.status(400).json({
2273	        error: `Plugin is not ready (current status: ${plugin.status})`,
2274	      });
2275	      return;
2276	    }
2277	
2278	    // Step 3: Validate the plugin has webhooks.receive capability
2279	    const manifest = plugin.manifestJson;
2280	    if (!manifest) {
2281	      res.status(400).json({ error: "Plugin manifest is missing" });
2282	      return;
2283	    }
2284	
2285	    const capabilities = manifest.capabilities ?? [];
2286	    if (!capabilities.includes("webhooks.receive")) {
2287	      res.status(400).json({
2288	        error: "Plugin does not have the webhooks.receive capability",
2289	      });
2290	      return;
2291	    }
2292	
2293	    // Step 4: Validate the endpointKey exists in the manifest's webhook declarations
2294	    const declaredWebhooks = manifest.webhooks ?? [];
2295	    const webhookDecl = declaredWebhooks.find(
2296	      (w) => w.endpointKey === endpointKey,
2297	    );
2298	    if (!webhookDecl) {
2299	      res.status(404).json({
2300	        error: `Webhook endpoint '${endpointKey}' is not declared by this plugin`,
2301	      });
2302	      return;
2303	    }
2304	
2305	    // Step 5: Extract request data
2306	    const requestId = randomUUID();
2307	    const rawHeaders: Record<string, string> = {};
2308	    for (const [key, value] of Object.entries(req.headers)) {
2309	      if (typeof value === "string") {
2310	        rawHeaders[key] = value;
2311	      } else if (Array.isArray(value)) {
2312	        rawHeaders[key] = value.join(", ");
2313	      }
2314	    }
2315	
2316	    // Use the raw buffer stashed by the express.json() `verify` callback.
2317	    // This preserves the exact bytes the provider signed, whereas
2318	    // JSON.stringify(req.body) would re-serialize and break HMAC verification.
2319	    const stashedRaw = (req as unknown as { rawBody?: Buffer }).rawBody;
2320	    const rawBody = stashedRaw ? stashedRaw.toString("utf-8") : "";
2321	    const parsedBody = req.body as unknown;
2322	    const payload = (req.body as Record<string, unknown> | undefined) ?? {};
2323	
2324	    // Step 6: Record the delivery in the database
2325	    const startedAt = new Date();
2326	    const [delivery] = await db
2327	      .insert(pluginWebhookDeliveries)
2328	      .values({
2329	        pluginId: plugin.id,
2330	        webhookKey: endpointKey,
2331	        status: "pending",
2332	        payload,
2333	        headers: rawHeaders,
2334	        startedAt,
2335	      })
2336	      .returning({ id: pluginWebhookDeliveries.id });
2337	
2338	    // Step 7: Dispatch to the worker via handleWebhook RPC
2339	    try {
2340	      await webhookDeps.workerManager.call(plugin.id, "handleWebhook", {
2341	        endpointKey,
2342	        headers: req.headers as Record<string, string | string[]>,
2343	        rawBody,
2344	        parsedBody,
2345	        requestId,
2346	      });
2347	
2348	      // Step 8: Update delivery record to success
2349	      const finishedAt = new Date();
2350	      const durationMs = finishedAt.getTime() - startedAt.getTime();
2351	      await db
2352	        .update(pluginWebhookDeliveries)
2353	        .set({
2354	          status: "success",
2355	          durationMs,
2356	          finishedAt,
2357	        })
2358	        .where(eq(pluginWebhookDeliveries.id, delivery.id));
2359	
2360	      res.status(200).json({
2361	        deliveryId: delivery.id,
2362	        status: "success",
2363	      });
2364	    } catch (err) {
2365	      // Step 8 (error): Update delivery record to failed
2366	      const finishedAt = new Date();
2367	      const durationMs = finishedAt.getTime() - startedAt.getTime();
2368	      const errorMessage = err instanceof Error ? err.message : String(err);
2369	
2370	      await db
2371	        .update(pluginWebhookDeliveries)
2372	        .set({
2373	          status: "failed",
2374	          durationMs,
2375	          error: errorMessage,
2376	          finishedAt,
2377	        })
2378	        .where(eq(pluginWebhookDeliveries.id, delivery.id));
2379	
2380	      res.status(502).json({
2381	        deliveryId: delivery.id,
2382	        status: "failed",
2383	        error: errorMessage,
2384	      });
2385	    }
2386	  });
